# =====================================================================
#  healthcare.map - phishing phrases for clinics, hospitals, pharmacies
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : lab / test results behind a link, patient portal login,
#           medical record and referral "documents", health insurance
#           claims, medical supplier invoices, patient complaints,
#           medical license / registration suspension, health-authority
#           notices, equipment recall notices
#
#  Avoided: appointment reminders and confirmations, "prescription is
#           ready for pickup", "your appointment is confirmed", because
#           clinics send real ones every day.
# =====================================================================

# ===== English =====
# Results / records
/(your|the\s+patient['’]?s?)\s+(lab|laboratory|test|blood\s+test|medical)\s+results?\s+(are|is)\s+(ready|available)\s+(to\s+view|for\s+download|online|via|click|here)/i
/(view|download|access)\s+(your\s+|the\s+)?(lab\s+results?|test\s+results?|medical\s+records?|scan\s+results?|diagnosis\s+report)\s+(here|below|online|via\s+(the\s+)?link)/i
/(patient\s+)?(referral|medical\s+report|discharge\s+summary)\s+(has\s+been\s+)?shared\s+with\s+you/i
/(sign\s+in|log\s+in|login)\s+to\s+(your\s+|the\s+)?(patient|health|medical)\s+portal\s+to\s+(view|access|download|verify)/i
/(your\s+)?(patient|health)\s+portal\s+(account\s+)?(will\s+be|has\s+been)\s+(suspended|deactivated|locked)/i
# Insurance
/(health|medical)\s+insurance\s+claim\s+(#?\S+\s+)?(has\s+been\s+)?(denied|rejected|approved|on\s+hold|requires\s+(your\s+)?action)/i
/(update|verify)\s+your\s+(health\s+)?insurance\s+(details|information|coverage)\s+(to\s+avoid|within|immediately)/i
# Suppliers / complaints
/(medical|pharmaceutical|lab)\s+suppl(y|ies|ier)\s+(invoice|payment)\s+(is\s+)?(overdue|outstanding|available\s+online|via\s+link)/i
/patient\s+complaint\s+(regarding|about)\s+(your\s+)?(treatment|clinic|doctor|staff)[^.]{0,40}(see|view|attached|link)/i
# License / authority
/(medical|nursing|pharmacy|clinic)\s+licen[cs]e\s+(will\s+be\s+|has\s+been\s+)?(suspended|revoked|expired|under\s+review)/i
/(ministry\s+of\s+health|health\s+authority|medical\s+council)\s+(notice|notification|inspection|penalty)/i
/(hipaa|gdpr)\s+(compliance\s+)?(violation|breach)\s+(notice|report|detected)/i
# Recalls
/(urgent\s+)?(medical\s+device|equipment|product)\s+recall\s+(notice|notification)[^.]{0,40}(click|view|download|link)/i

